def s2_fig(
    C_ANALYSIS, C_OBS, C_PERT, C_TRUTH, GRAD_ALPHAS, GRAD_BLIND_EXACT,
    GRAD_BLIND_NOBG, GRAD_EXACT, GRAD_NOBG, GRAD_SCALED, SQRT_EPS, finish_mpl,
    mpl_panels, np,
):
    _a = np.asarray(GRAD_ALPHAS)
    _fig, (_ax0, _ax1) = mpl_panels(
        ncols=2,
        titles=("Tested away from the background", "Tested AT the background"),
        height=3.9,
    )

    for _y, _c, _lab in (
        (GRAD_EXACT, C_TRUTH, "exact gradient"),
        (GRAD_SCALED, C_PERT, "every component 1 % too large"),
        (GRAD_NOBG, C_OBS, r"$J_b$ term missing from $\nabla J$"),
    ):
        _ax0.loglog(_a, np.asarray(_y), "o-", color=_c, markersize=3,
                    linewidth=1.4, label=_lab)
    _ax0.axhline(SQRT_EPS, color=C_ANALYSIS, linestyle=":", linewidth=1.2)
    _ax0.text(_a[1], SQRT_EPS * 1.5, r"$\sqrt{\varepsilon}$", fontsize=8,
              color=C_ANALYSIS)
    _ax0.legend(loc="lower left", fontsize=7.5, framealpha=0.9)

    # GRAD_BLIND_EXACT, not GRAD_EXACT: both curves in this panel must come
    # from the same test point or the comparison means nothing.
    _ax1.loglog(_a, np.asarray(GRAD_BLIND_EXACT), "o-", color=C_TRUTH,
                markersize=3, linewidth=1.4, label="exact gradient")
    _ax1.loglog(_a, np.asarray(GRAD_BLIND_NOBG), "--", color=C_OBS,
                linewidth=2.6, alpha=0.8,
                label=r"$J_b$ term missing — indistinguishable")
    _ax1.legend(loc="lower left", fontsize=7.5, framealpha=0.9)

    for _ax in (_ax0, _ax1):
        _ax.set_xlabel(r"$\alpha$")
        _ax.set_ylim(1e-9, 5.0)
    _ax0.set_ylabel(r"$|\Phi(\alpha) - 1|$")

    finish_mpl(_fig, "The gradient test, and the one place it is blind")
    return


@app.cell(hide_code=True)
def s2_note(GRAD_ALPHAS, GRAD_EXACT, GRAD_NOBG, GRAD_SCALED, mo, np):
    _a = np.asarray(GRAD_ALPHAS)
    _mid = (_a > 4e-12) & (_a < 6e-7)
    _span = lambda v: np.asarray(v)[_mid].max() / np.asarray(v)[_mid].min()  # noqa: E731
    mo.md(
        rf"""
    **Read the left panel as a shape, not as a number.** The right-hand branch falls
    with slope 1 — it is the neglected $O(\alpha^2)$ curvature divided by $\alpha$. The
    left-hand branch rises like $1/\alpha$, because the numerator is a difference of two
    nearly equal numbers and its relative error grows as the difference shrinks. Between
    them is a floor at ${np.asarray(GRAD_EXACT).min():.1e}$, close to
    $\sqrt{{\varepsilon}} \approx 1.5\times10^{{-8}}$, which is what a first-order
    difference can achieve and has nothing to do with whether the gradient is right.

    **A wrong gradient does not fail to turn upward — it fails to descend.** Both broken
    gradients rise at small $\alpha$ exactly like the correct one, because that branch
    comes from evaluating $J$ and knows nothing about $\nabla J$. What they cannot do is
    reach the floor. Over the middle decades the exact gradient falls by a factor of
    {_span(GRAD_EXACT):.0f}; the 1 %-scaled one by {_span(GRAD_SCALED):.2f} and the
    one missing its background term by {_span(GRAD_NOBG):.2f}. **The diagnostic is the
    depth of the trough**, and a plateau is a failure however far down it sits.

    **The right panel is a trap worth knowing about.** Run the same test at
    $x_0 = x^b$ and the curve for the gradient missing its entire background term is
    *bitwise identical* to the correct one. The reason is immediate once seen: that term
    is $\mathbf{{B}}^{{-1}}(x_0 - x^b)$, which is exactly zero at the background — and the
    background is the obvious place to start a test. Test at a displaced point.
    """
    )
    return


# ===========================================================================
# Section 3
# ===========================================================================
@app.cell(hide_code=True)
def s3_md(PARTIAL_NOBS, PARTIAL_WINDOW, mo):
    mo.md(
        rf"""
    ## 3 · What the model-as-constraint buys

    Here is the experiment that separates 3D-Var from 4D-Var most sharply. Observe
    **only $x$** — {PARTIAL_NOBS} measurements of it, spread over a {PARTIAL_WINDOW} TU
    window — and ask what happens to $y$ and $z$.

    For 3D-Var with a diagonal $\mathbf{{B}}$ the answer is arithmetic. The analysis
    increment is $\mathbf{{B}}\mathbf{{H}}^{{\top}}(\mathbf{{H}}\mathbf{{B}}\mathbf{{H}}^{{\top}}
    +\mathbf{{R}})^{{-1}}d$, and with $\mathbf{{H}} = (1\;0\;0)$ and diagonal
    $\mathbf{{B}}$, $\mathbf{{B}}\mathbf{{H}}^{{\top}}$ has non-zero entries only in its
    first row. The increment lives entirely in $x$. **$y$ and $z$ are returned bitwise
    unchanged.** 3D-Var has no mechanism to reach them.

    4D-Var does, and not by assuming anything about correlations. The trajectory
    launched from $x_0$ depends on all three components, so a mismatch between the
    predicted and observed $x$ *later in the window* is information about $y$ and $z$
    *now*. The model is acting as a constraint rather than as an interpolator.

    This is not a Lorenz-63 curiosity. It is why operational 4D-Var can assimilate
    satellite radiances, radar reflectivity and GPS radio-occultation bending angles —
    quantities that are not model variables at all, and that constrain the model state
    only through the dynamics and the observation operator.
    """
    )
    return


@app.cell(hide_code=True)
def s3_fig(
    C_ANALYSIS, C_BG, C_SPREAD, PARTIAL_BKG, PARTIAL_CASES, PARTIAL_FOUR,
    PARTIAL_THREE, finish_mpl, mpl_panels, np,
):
    _labels = ("$x$\nobserved", "$y$\nnot observed", "$z$\nnot observed")
    _series = (
        ("background", np.asarray(PARTIAL_BKG), C_BG),
        ("3D-Var", np.asarray(PARTIAL_THREE), C_SPREAD),
        ("4D-Var", np.asarray(PARTIAL_FOUR), C_ANALYSIS),
    )
    _fig, (_ax,) = mpl_panels(ncols=1, figsize=(8.4, 4.0))
    _x = np.arange(3)
    _w = 0.26
    for _i, (_name, _values, _colour) in enumerate(_series):
        _ax.bar(_x + (_i - 1) * _w, _values, _w, color=_colour, label=_name,
                edgecolor="white", linewidth=0.8)
        for _xi, _v in zip(_x + (_i - 1) * _w, _values):
            _ax.text(_xi, _v + 0.015, f"{_v:.2f}", ha="center", fontsize=7.5,
                     color="#4a4460")
    _ax.set_xticks(_x)
    _ax.set_xticklabels(_labels)
    _ax.set_ylabel(f"RMS analysis error over {PARTIAL_CASES} cases")
    _ax.set_ylim(0.0, 1.42)
    _ax.legend(fontsize=8, framealpha=0.95, ncols=3, loc="upper center")
    finish_mpl(_fig, "Observing $x$ alone: only 4D-Var reaches $y$ and $z$")
    return


@app.cell(hide_code=True)
def s3_note(PARTIAL_BKG, PARTIAL_FOUR, PARTIAL_THREE, mo, np):
    _b = np.asarray(PARTIAL_BKG)
    _t = np.asarray(PARTIAL_THREE)
    _f = np.asarray(PARTIAL_FOUR)
    mo.md(
        rf"""
    4D-Var cuts the error in the **unobserved** $y$ from {_b[1]:.3f} to {_f[1]:.3f}, a
    reduction of {100 * (1 - _f[1] / _b[1]):.0f} %, using observations that never
    touched $y$. The observed $x$ improves by a similar
    {100 * (1 - _f[0] / _b[0]):.0f} %.

    Two honest qualifications. **$z$ barely moves** — {_b[2]:.3f} to {_f[2]:.3f}. Over
    half a time unit the Lorenz flow does not couple $z$ back into $x$ strongly enough
    for six measurements to pin it down; observability through the dynamics is real but
    it is not uniform, and which directions are well determined is exactly what the
    Hessian in section 4 describes.

    **3D-Var's $x$ gets very slightly worse**, {_b[0]:.4f} to {_t[0]:.4f}. That is not a
    bug either. A single observation with $\sigma_o = 2$ is *less* informative than a
    background with $\sigma_b \approx 1$, so the analysis is pulled away from a good
    first guess towards a noisy measurement — correctly weighted, and still on average
    slightly worse for that one draw of noise. Assimilating a weak observation is not
    guaranteed to help on any particular day; it is guaranteed to help in expectation
    only when $\mathbf{{B}}$ and $\mathbf{{R}}$ are right.
    """
    )
    return


# ===========================================================================
# Section 4
# ===========================================================================
@app.cell(hide_code=True)
def s4_md(mo):
    mo.md(
        r"""
    ## 4 · The Hessian is the analysis-error covariance

    4D-Var never forms a covariance matrix. It is often described, for that reason, as a
    scheme that produces a state but no uncertainty — the standard complaint against it,
    and the standard argument for the ensemble methods of chapter 19. The complaint is
    half right at most, because the uncertainty is already there, in the curvature of
    the cost function:

    $$
    \mathbf{A}^{-1} \;=\; \nabla^2 J \;=\; \mathbf{B}^{-1}
      + \sum_k \mathbf{M}_k^{\top}\mathbf{H}^{\top}\mathbf{R}^{-1}\mathbf{H}\mathbf{M}_k .
    $$

    Sharp curvature means the observations pinned the state down; flat curvature means
    they did not. Two properties of this matrix carry the rest of the chapter.

    **It does not depend on the observed values** — only on where and when the
    observations are, and on the trajectory. So the analysis uncertainty can be computed
    *before any observation exists*, which is what makes the targeting studies of
    chapter 16 possible.

    **It is flow-dependent even though $\mathbf{B}$ is not.** The propagators carry the
    local dynamics into it. 3D-Var's Hessian is
    $\mathbf{B}^{-1} + \mathbf{H}^{\top}\mathbf{R}^{-1}\mathbf{H}$ at every point of the
    attractor and at every time, forever; the same ellipse on a quiet day and on the day
    a forecast is about to fail.

    That this is not a formal analogy is worth checking exactly. For **linear** dynamics
    a perfect-model 4D-Var over a window is the Kalman filter: not approximately, not in
    some limit, but algebraically.
    """
    )
    return


@app.cell(hide_code=True)
def s4_kalman(KALMAN_COV_GAP, KALMAN_MEAN_GAP, mo):
    mo.md(
        rf"""
    /// admonition | Verified: 4D-Var $\equiv$ the Kalman filter, for linear dynamics
        type: info

    On a linear three-variable system, with one outer iteration of the incremental
    solver:

    | Quantity | Agreement |
    |---|---|
    | $\mathcal{{M}}(x^a_0)$ against the Kalman analysis **mean** at the window end | ${KALMAN_MEAN_GAP:.1e}$ |
    | $\mathbf{{M}}\mathbf{{A}}\mathbf{{M}}^{{\top}}$ against the Kalman analysis **covariance** | ${KALMAN_COV_GAP:.1e}$ |

    Machine precision, not tolerance. The two agree exactly because
    `tangent_linear_propagator` steps the tangent through the *same* RK4 stages as the
    nonlinear model, so for a linear right-hand side both are the same matrix polynomial
    in the timestep. `chaoslib` asserts both as tests.
    ///
    """
    )
    return


@app.cell(hide_code=True)
def s4_md2(HESS_POINTS, HESS_TIMES, mo):
    mo.md(
        rf"""
    ### Does spreading observations in time actually pay?

    The comparison that matters is not 4D-Var against 3D-Var — 4D-Var uses more
    observations, so of course it wins. The fair control holds the observation *count*
    fixed and moves only their *timing*: {len(HESS_TIMES)} observations of the full
    state, either all at the analysis time, or spread across the window. Both are
    analyses valid at the same instant. The question is which one forecasts better.

    Below, the ratio of the trace of the forecast-error covariance,
    $\operatorname{{tr}}(\mathbf{{M}}\mathbf{{A}}\mathbf{{M}}^{{\top}})$, spread over
    concentrated, at {HESS_POINTS} points around the attractor. Below 1 means spreading
    won. The ratio is formed **per state and then summarised**, because the traces
    themselves are heavy-tailed across the attractor and a ratio of medians would be a
    different and much more flattering number.
    """
    )
    return


@app.cell(hide_code=True)
def s4_fig(
    C_ANALYSIS, C_PERT, C_SPREAD, C_TRUTH, HESS_LOOSE_ALIGNED,
    HESS_LOOSE_DIVISOR, HESS_LOOSE_ORTHOGONAL, HESS_TIGHT_ALIGNED,
    HESS_TIGHT_DIVISOR, HESS_TIGHT_ORTHOGONAL, LEADS, LEAD_LOOSE_LOWER,
    LEAD_LOOSE_MEDIAN, LEAD_LOOSE_UPPER, LEAD_TIGHT_LOWER, LEAD_TIGHT_MEDIAN,
    LEAD_TIGHT_UPPER, finish_mpl, mpl_panels, np,
):
    _leads = np.asarray(LEADS)
    _fig, (_ax0, _ax1) = mpl_panels(
        ncols=2,
        titles=(
            "Forecast error: spread / concentrated",
            "Orientation of $\\mathbf{A}$",
        ),
        figsize=(9.6, 4.1),
    )

    for _med, _lo, _hi, _c, _lab in (
        (LEAD_TIGHT_MEDIAN, LEAD_TIGHT_LOWER, LEAD_TIGHT_UPPER, C_TRUTH,
         f"tight $\\mathbf{{B}}$ (clim/{int(HESS_TIGHT_DIVISOR)})"),
        (LEAD_LOOSE_MEDIAN, LEAD_LOOSE_LOWER, LEAD_LOOSE_UPPER, C_PERT,
         f"loose $\\mathbf{{B}}$ (clim/{int(HESS_LOOSE_DIVISOR)})"),
    ):
        _ax0.plot(_leads, np.asarray(_med), "o-", color=_c, markersize=4,
                  linewidth=1.6, label=_lab)
        _ax0.fill_between(_leads, np.asarray(_lo), np.asarray(_hi), color=_c,
                          alpha=0.14, linewidth=0)
    _ax0.axhline(1.0, color="#8b8698", linestyle="--", linewidth=1.1)
    _ax0.text(_leads[-1], 1.04, "spreading gains nothing", ha="right",
              fontsize=7.5, color="#6b6580")
    _ax0.set_xlabel("forecast lead from the analysis (TU)")
    _ax0.set_ylabel("paired ratio (median, IQR)")
    # 1.43 at lead 0 with a loose B is the headline number of this section;
    # an axis that clips it hides the result the figure exists to show.
    _ax0.set_ylim(0.0, 1.62)
    _ax0.legend(loc="lower right", fontsize=7.5, framealpha=0.9)

    _bins = np.linspace(0.0, 90.0, 19)
    for _values, _c, _lab, _style in (
        (HESS_LOOSE_ALIGNED, C_ANALYSIS,
         f"least-uncertain axis, clim/{int(HESS_LOOSE_DIVISOR)}", "-"),
        (HESS_LOOSE_ORTHOGONAL, C_SPREAD,
         f"most-uncertain axis, clim/{int(HESS_LOOSE_DIVISOR)}", "-"),
        (HESS_TIGHT_ALIGNED, C_ANALYSIS,
         f"least-uncertain axis, clim/{int(HESS_TIGHT_DIVISOR)}", "--"),
    ):
        _counts, _ = np.histogram(np.asarray(_values), bins=_bins)
        _ax1.step(_bins[:-1], _counts, where="post", color=_c, linewidth=1.7,
                  linestyle=_style, label=_lab)
    _ax1.set_xlabel("angle to the leading singular vector (degrees)")
    _ax1.set_ylabel("attractor points")
    _ax1.set_xlim(0, 90)
    _ax1.set_ylim(0, 34)
    _ax1.legend(loc="upper left", fontsize=6.8, framealpha=0.95)

    finish_mpl(_fig, None)
    return


@app.cell(hide_code=True)
def s4_note(
    HESS_LOOSE_ALIGNED, HESS_LOOSE_DIVISOR, HESS_LOOSE_ORTHOGONAL,
    HESS_TIGHT_ALIGNED, HESS_TIGHT_DIVISOR, LEADS, LEAD_LOOSE_MEDIAN,
    LEAD_TIGHT_MEDIAN, mo, np,
):
    _leads = np.asarray(LEADS)
    _t = np.asarray(LEAD_TIGHT_MEDIAN)
    _l = np.asarray(LEAD_LOOSE_MEDIAN)
    _i25 = int(np.argmin(np.abs(_leads - 0.25)))
    mo.md(
        rf"""
    **At the analysis time, spreading the observations does not help — and with a loose
    background it actively hurts.** The ratio is {_t[0]:.2f} with a tight background and
    {_l[0]:.2f} with a loose one: concentrating all six observations at the analysis time
    gives an analysis with {100 * (_l[0] - 1):.0f} % *less* total error variance. Judged
    the way analyses are usually judged — against the truth, at the analysis time — the
    four-dimensional arrangement is the worse of the two.

    **By a quarter of a time unit into the forecast the ratio is {_t[_i25]:.2f} and
    {_l[_i25]:.2f}**, and it stays below 1 at every subsequent lead. The same
    observational information, differently arranged in time, has gone from
    {100 * (_l[0] - 1):.0f} % worse to a factor of {1 / _l[_i25]:.1f} better. The
    crossover happens inside the first tenth of a time unit, and the entire benefit is
    invisible at the moment the analysis is verified.

    The mechanism is in the right panel, and it is **conditional**, which is why it is
    plotted at two background qualities. With a loose $\mathbf{{B}}$ — the observations
    shaping $\mathbf{{A}}$ — the least-uncertain axis of the analysis-error covariance
    lies a median of {np.median(np.asarray(HESS_LOOSE_ALIGNED)):.0f}° from the leading
    singular vector and the most-uncertain axis
    {np.median(np.asarray(HESS_LOOSE_ORTHOGONAL)):.0f}° from it. The window constrains
    the growing directions best, precisely *because* they grow into the observations,
    and what error survives lies where the flow will not amplify it.

    Tighten $\mathbf{{B}}$ and the alignment weakens to
    {np.median(np.asarray(HESS_TIGHT_ALIGNED)):.0f}°: when the background dominates the
    Hessian, $\mathbf{{A}}$ inherits $\mathbf{{B}}$'s shape rather than the flow's. The
    effect is real but it is a statement about which term dominates, not a universal
    property of 4D-Var — and the forecast-error gain in the left panel survives at both.
    """
    )
    return


